def solution(to_currency, values_list):
    rate = 1.1363636
    results = []
    for value in values_list:
        if to_currency == 'USD':
            converted = round(value * rate, 2)
            formatted = f'${converted:,.2f}'
        else:
            converted = round(value / rate, 2)
            formatted = f'{converted:,.2f}€'
        results.append(formatted)
    return results
